//==============================================================================
// Module: vending_machine
// Description: Automatic Beverage Vending Machine FSM
// Auto-generated by Spec2RTL Engine
//==============================================================================
module vending_machine (
    input  wire       clk,
    input  wire       clr,
    input  wire       coin_5k,    // 5.000 VND inserted
    input  wire       coin_10k,   // 10.000 VND inserted
    output reg        dispense,   // 1: Dispense beverage
    output reg        change_5k,  // 1: Return 5.000 VND change
    output reg  [4:0] balance,    // Current balance in thousands (0, 5, 10, 15, 20)
    output wire [2:0] state_out
);

    localparam S_0K        = 3'b000;
    localparam S_5K        = 3'b001;
    localparam S_10K       = 3'b010;
    localparam S_DISPENSE  = 3'b011; // 15k: Dispense
    localparam S_CHANGE    = 3'b100; // 20k: Dispense + 5k change

    reg [2:0] state, next_state;

    assign state_out = state;

    always @(posedge clk or posedge clr) begin
        if (clr)
            state <= S_0K;
        else
            state <= next_state;
    end

    always @(*) begin
        next_state = state;
        case (state)
            S_0K: begin
                if (coin_10k)
                    next_state = S_10K;
                else if (coin_5k)
                    next_state = S_5K;
            end

            S_5K: begin
                if (coin_10k)
                    next_state = S_DISPENSE;
                else if (coin_5k)
                    next_state = S_10K;
            end

            S_10K: begin
                if (coin_10k)
                    next_state = S_CHANGE;
                else if (coin_5k)
                    next_state = S_DISPENSE;
            end

            S_DISPENSE: next_state = S_0K;
            S_CHANGE:   next_state = S_0K;
            default:    next_state = S_0K;
        endcase
    end

    always @(*) begin
        case (state)
            S_0K: begin
                dispense  = 1'b0;
                change_5k = 1'b0;
                balance   = 5'd0;
            end
            S_5K: begin
                dispense  = 1'b0;
                change_5k = 1'b0;
                balance   = 5'd5;
            end
            S_10K: begin
                dispense  = 1'b0;
                change_5k = 1'b0;
                balance   = 5'd10;
            end
            S_DISPENSE: begin
                dispense  = 1'b1;
                change_5k = 1'b0;
                balance   = 5'd15;
            end
            S_CHANGE: begin
                dispense  = 1'b1;
                change_5k = 1'b1;
                balance   = 5'd20;
            end
            default: begin
                dispense  = 1'b0;
                change_5k = 1'b0;
                balance   = 5'd0;
            end
        endcase
    end

endmodule
